import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr02111Controller {
  @Post('/retirement-pays/generate-receipt')
  @HttpCode(200)
  async generateRetirementPayReceipt(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const rawId = data['employeeId'];
    if (rawId === undefined || rawId === null || rawId === '' || !/^[0-9]+$/.test(String(rawId))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '퇴직 임직원을 올바르게 입력해 주세요.');
    }
    const employeeId = String(rawId);
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      // 영수증은 산정된 퇴직금(산정액이 채워진 가장 최근 퇴직일 이력)을 기준으로 생성한다.
      const rows = await db.query(
        `SELECT retirement_pay_id AS "retirementPayId",
                employee_id AS "employeeId",
                retirement_date AS "retirementDate",
                calculated_amount AS "calculatedAmount",
                withholding_tax AS "withholdingTax"
           FROM retirement_pay
          WHERE employee_id = CAST(:employeeId AS bigint)
            AND calculated_amount IS NOT NULL
          ORDER BY retirement_date DESC, retirement_pay_id DESC
          LIMIT 1`,
        { employeeId },
      );
      if (rows.length === 0) {
        throw new ApiError(422, 'RETIREMENT_PAY_NOT_CALCULATED', '퇴직금 산정 이력이 없어 영수증을 생성할 수 없습니다.');
      }
      return rows[0];
    });
  }
}

