import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Band,
  DataTable,
  Drawer,
  Pairs,
  Form,
  Field,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02111Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [selected, setSelected] = useState<Row | null>(null);

  const submit = async () => {
    if (employeeId === '' || employeeId === undefined) {
      throw new Error('퇴직 임직원을 선택해 주세요.');
    }
    const res = await call('POST', '/retirement-pays/generate-receipt', role, { employeeId });
    setResults((prev) => [res, ...prev.filter((r) => r['retirementPayId'] !== res['retirementPayId'])]);
    setCreating(false);
    setEmployeeId('');
    setSelected(res);
    notify('퇴직소득 원천징수영수증을 생성했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>생성한 영수증</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setCreating(true)}>
            영수증 생성
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'employeeId', label: '퇴직 임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r['retirementDate']} /> },
            { key: 'calculatedAmount', label: '퇴직금 산정액', render: (r) => <Num value={r['calculatedAmount']} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r['withholdingTax']} /> },
          ]}
          rows={results}
          onRowClick={(r) => setSelected(r)}
          empty="생성한 영수증이 없습니다. 영수증 생성 버튼을 눌러 주세요."
        />
      </section>
      {creating && (
        <Drawer title="퇴직소득 원천징수영수증 생성" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="생성">
            <Field label="퇴직 임직원" required wide>
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {selected && (
        <Drawer title="퇴직소득 원천징수영수증" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['퇴직금 ID', String(selected['retirementPayId'] ?? '')],
              ['퇴직 임직원', <RefName table="employee" role={role} value={selected['employeeId']} />],
              ['퇴직일', <DateText value={selected['retirementDate']} />],
              ['퇴직금 산정액', <Num value={selected['calculatedAmount']} />],
              ['원천징수세액', <Num value={selected['withholdingTax']} />],
            ]}
          />
          <button type="button" onClick={() => window.print()}>
            출력
          </button>
        </Drawer>
      )}
    </div>
  );
}
